from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20
    CONTRACTS = 1

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False,
            leverage=1,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(self.FAST_PERIOD)
        self.slow = SimpleMovingAverage(self.SLOW_PERIOD)

        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None
        self.exit_submitted = False
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.no_entry_today is False:
            self._process_expiration_safety(slice)

        self._process_time_stop()
        self._process_profit_target(slice)

        if self.held_contract is not None or self._entry_order_is_open():
            self._process_spy_assignment()
            return

        if self.no_entry_today:
            self._process_spy_assignment()
            return

        if self.spy not in slice.Bars:
            self._process_spy_assignment()
            return

        minute_bar = slice.Bars[self.spy]
        consolidated = self._update_five_minute_bar(minute_bar)

        if consolidated is not None:
            self._evaluate_crossover_and_enter(consolidated, slice)

        self._process_spy_assignment()

    def _update_five_minute_bar(self, minute_bar):
        local_time = minute_bar.EndTime.astimezone(
            self.TimeZone
        ) if minute_bar.EndTime.tzinfo else minute_bar.EndTime

        # Minute bars ending at 09:31 through 09:35 belong to the
        # five-minute bar ending at 09:35.
        bucket_end = local_time.replace(
            minute=((local_time.minute // 5) + 1) * 5,
            second=0,
            microsecond=0
        )

        if bucket_end.minute == 60:
            bucket_end = bucket_end.replace(
                hour=bucket_end.hour + 1,
                minute=0
            )

        if self.current_bucket is None:
            self.current_bucket = bucket_end

        if bucket_end != self.current_bucket:
            completed = self._build_bar_if_complete()

            self.current_bucket = bucket_end
            self.bucket_bars = [minute_bar]
            return completed

        self.bucket_bars.append(minute_bar)
        return None

    def _build_bar_if_complete(self):
        bars = self.bucket_bars

        if len(bars) != 5:
            self.bucket_bars = []
            return None

        bars = sorted(bars, key=lambda bar: bar.EndTime)

        expected = bars[0].EndTime
        for bar in bars:
            if bar.EndTime != expected:
                self.bucket_bars = []
                return None
            expected += timedelta(minutes=1)

        first = bars[0]
        last = bars[-1]

        consolidated = TradeBar(
            last.EndTime,
            self.spy,
            first.Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            last.Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self.bucket_bars = []
        return consolidated

    def _evaluate_crossover_and_enter(self, bar, slice):
        bar_time = bar.EndTime.time()

        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if old_fast is None or old_slow is None:
            return

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            old_fast <= old_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        self._select_and_enter_option(slice, bar.Close)

    def _select_and_enter_option(self, slice, spy_price):
        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        algorithm_date = self.Time.date()
        minimum_expiration = algorithm_date + timedelta(days=7)

        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                symbol = contract.Symbol
                expiration = symbol.ID.Date.date()

                if expiration < minimum_expiration:
                    continue
                if symbol.ID.OptionRight != OptionRight.Call:
                    continue
                if symbol.ID.StrikePrice < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiration = min(
            contract.Symbol.ID.Date.date()
            for contract in candidates
        )

        candidates = [
            contract for contract in candidates
            if contract.Symbol.ID.Date.date() == nearest_expiration
        ]

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Symbol.ID.StrikePrice,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            self.CONTRACTS,
            tag="Bullish five-minute crossover entry"
        )

    def _process_profit_target(self, slice):
        if self.held_contract is None or self.entry_price is None:
            return
        if self.exit_submitted:
            return

        contract = None

        for chain in slice.OptionChains.Values:
            if self.held_contract in chain.Contracts:
                contract = chain.Contracts[self.held_contract]
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_time_stop(self):
        if self.held_contract is None or self.exit_submitted:
            return

        expiration = self.held_contract.ID.Date.date()
        if self.Time.date() != expiration - timedelta(days=1):
            return

        if self.Time.time() >= time(15, 45):
            self._submit_exit("expiration time stop")

    def _process_expiration_safety(self, slice):
        if self.held_contract is None:
            return

        expiration = self.held_contract.ID.Date.date()

        if self.Time.date() >= expiration:
            self.no_entry_today = True

            if not self.exit_submitted:
                self._submit_exit("expiration safety liquidation")

    def _submit_exit(self, reason):
        if self.held_contract is None or self.exit_submitted:
            return

        self.exit_submitted = True

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted,
                          OrderStatus.PartiallyFilled):
                self.exit_ticket.Cancel("Replaced by required liquidation")

        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            -self.CONTRACTS,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {0} ({1})".format(
                self.held_contract,
                reason
            )
        )

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_contract = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.exit_submitted = False

                    self.Debug(
                        "Entry filled: {0} at {1}".format(
                            self.held_contract,
                            self.entry_price
                        )
                    )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {0} at {1}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.held_contract = None
                    self.entry_price = None
                    self.exit_ticket = None
                    self.exit_submitted = False

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.exit_ticket = None
                    self.exit_submitted = False

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentOrderEvent):
        self.Debug(
            "Unexpected option exercise or assignment: {0}".format(
                assignment_event
            )
        )
        self.no_entry_today = True

        if self.Portfolio[self.spy].Invested:
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="Liquidate unexpected assignment"
            )

    def _process_spy_assignment(self):
        if self.Portfolio[self.spy].Invested and self.held_contract is None:
            self.Debug("Unexpected SPY equity position detected; liquidating.")
            self.no_entry_today = True
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="Liquidate unexpected SPY position"
            )
