class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = RollingWindow[float](self.fast_period)
        self.slow_values = RollingWindow[float](self.slow_period)

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_fill_price = None
        self.no_entry_today = False
        self.pending_signal = False

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # TradeBarConsolidator emits bars only when actual minute data exists.
        self.fast_values.Add(float(bar.Close))
        self.slow_values.Add(float(bar.Close))

        if not self.fast_values.IsReady or not self.slow_values.IsReady:
            return

        previous_fast = self.fast_values[1] if self.fast_values.Count > 1 else None
        previous_slow = self.slow_values[1] if self.slow_values.Count > 1 else None

        if previous_fast is None or previous_slow is None:
            return

        current_time = bar.EndTime
        if not (current_time.hour > 9 or
                (current_time.hour == 9 and current_time.minute >= 45)):
            return

        if not (current_time.hour < 14 or
                (current_time.hour == 14 and current_time.minute <= 30)):
            return

        if previous_fast <= previous_slow and self.fast_values[0] > self.slow_values[0]:
            self.pending_signal = True

    def OnData(self, slice):
        current_date = self.Time.date()

        # Immediately liquidate unexpected SPY equity from exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"Unexpected exercise/assignment handling: liquidating "
                f"{spy_quantity} SPY shares at {self.Time}"
            )
            self.Liquidate(self.spy, "Unexpected exercise or assignment")
            self.no_entry_today = True

        # Expiration-day protection.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if current_date >= expiry_date:
                self.no_entry_today = True
                self._liquidate_option("Expiration-day liquidation")
            elif self._is_trading_day_before_expiration(current_date, expiry_date):
                if self.Time.hour > 15 or (
                    self.Time.hour == 15 and self.Time.minute >= 45
                ):
                    self._liquidate_option("Pre-expiration time stop")

        # Profit target is evaluated on every minute Slice.
        if self.held_option is not None and self.entry_fill_price is not None:
            contract = self._find_held_contract(slice)
            if contract is not None:
                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.50 * self.entry_fill_price:
                        self._liquidate_option("50% profit target")

        # Do not enter while holding, while an entry is open, or after expiration
        # processing has begun for the day.
        if not self.pending_signal:
            return

        self.pending_signal = False

        if self.no_entry_today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self._ticket_is_done(self.entry_ticket):
            return

        chain = self._get_spy_chain(slice)
        if chain is None:
            self.Debug(f"Skipped entry: no SPY option chain at {self.Time}")
            return

        algorithm_date = self.Time.date()
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not eligible_expiries:
            self.Debug(f"Skipped entry: no eligible expiration at {self.Time}")
            return

        selected_expiry = eligible_expiries[0]
        spy_price = float(self.Securities[self.spy].Price)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
